insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-17a', 'world-17', 'bare-metal', '17A - Bare Metal', 'Byte built a safe, sandboxed replica of the compiled component Zayn caught -- learn C, memory and compilation by taking it apart.', 1);
insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-17a-1', 'campaign-17a', 'foundations', 'Foundations', 'Memory, pointers and the C toolchain, learned by mapping how a real program actually sits in memory.', 1),
  ('operation-17a-2', 'campaign-17a', 'investigation', 'Investigation', 'Trace the replica''s own logic far enough to explain what it does to an input buffer.', 2);
insert into public.missions (
insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-w17-01', 1, 'byte', 'Zayn caught something World 16 couldn''t explain -- a compiled component with no readable source. I built a sandboxed, harmless copy of it so you can take it apart without going anywhere near the real one.'),
  ('mission-w17-01', 2, 'byte', 'This world moves slower than the last few. C, memory, pointers, how source becomes a running program. It''s not exciting yet. It will be, later, when it''s the only thing standing between you and something that actually bites.'),
  ('mission-w17-01', 3, 'ava', 'Byte''s right to slow down here. Every shortcut you take in this world is a hole you''ll fall into in a much more dangerous one.'),
  ('mission-w17-01', 4, 'byte', 'Replica''s loaded. Harmless, I promise -- I stripped anything that could actually do damage. Let''s start with where a program even lives while it runs.'),
  ('mission-w17-02', 1, 'byte', 'Every running program keeps its code, its globals, its dynamic allocations and its function calls in different places. Mixing them up is where a lot of memory bugs start.'),
  ('mission-w17-03', 1, 'byte', 'A pointer doesn''t hold a value. It holds a promise about where a value lives. Chase the promise, not the variable name.'),
  ('mission-w17-04', 1, 'byte', 'You wrote a .c file. That''s not what''s running on the machine. Something has to turn it into that, in a specific order, and skipping a step breaks everything downstream.'),
  ('mission-w17-05', 1, 'byte', 'When one function calls another, there''s an unwritten handshake about who saves what, where the arguments go, and how control comes back. That handshake is the calling convention.'),
  ('mission-w17-06', 1, 'byte', 'This is the replica''s core routine. It takes an input buffer and transforms it into something else. Explain exactly how, and pull out what''s hidden inside it.'),
  ('mission-w17-06', 2, 'byte', '...Got it. That''s not garbage output -- that''s a structured token.'),
  ('mission-w17-06', 3, 'ava', 'Byte, tell me that''s not what I think it is.'),
  ('mission-w17-06', 4, 'byte', 'It''s an API key. Real format, real-looking service identifier. Whatever this replica actually shipped from, it was talking to a live web service.'),
  ('mission-w17-06', 5, 'ava', 'Then the next question isn''t about memory anymore. It''s about that service, and every incident since where it might have been used. Web applications and databases -- that''s where we go next.');
insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-w17-01-o1', 'mission-w17-01', 1, 'Acknowledge the briefing', 'Confirm you''re ready to slow down and build real fundamentals.'),
  ('mission-w17-02-o1', 'mission-w17-02', 1, 'Map the regions', 'Order the memory regions from lowest to highest typical address.'),
  ('mission-w17-03-o1', 'mission-w17-03', 1, 'Trace the pointer', 'Determine what a chain of pointer reassignments actually prints.'),
  ('mission-w17-04-o1', 'mission-w17-04', 1, 'Order the toolchain', 'Put the stages of turning source into a running binary in the right order.'),
  ('mission-w17-05-o1', 'mission-w17-05', 1, 'Order the call sequence', 'Put the steps of a function call''s stack setup in the right order.'),
  ('mission-w17-06-o1', 'mission-w17-06', 1, 'Trace the transformation', 'Identify the evidence that explains exactly how the buffer is transformed.'),
  ('mission-w17-06-o2', 'mission-w17-06', 2, 'Recover the token', 'Identify how to reverse the transformation and recover the original buffer.'),
  ('mission-w17-06-o3', 'mission-w17-06', 3, 'Close the investigation', 'Submit the full explanation: the transformation and the recovered token.');
insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-w17-01-o1-c1', 'mission-w17-01-o1', 1, 'story_dialogue', 'Confirm you''re ready to continue.', '{"lines":[{"characterId":"byte","text":"Ready to start from zero? No shortcuts this time."}]}'::jsonb, '{"acknowledged":true}'::jsonb),
  ('mission-w17-02-o1-c1', 'mission-w17-02-o1', 1, 'interactive_diagram', 'Order these memory regions from the lowest typical address to the highest.', '{"hotspots":[{"id":"code","label":"Code / text segment","explanation":"Holds the compiled instructions themselves. Fixed size, typically read-only, set at compile time."},{"id":"data","label":"Global / static data","explanation":"Holds global and static variables. Size is fixed at compile time, but the values can change at runtime."},{"id":"heap","label":"Heap","explanation":"Dynamically allocated memory (malloc). Grows upward as the program requests more."},{"id":"stack","label":"Stack","explanation":"Holds local variables and function call frames. Grows downward as functions call other functions."}],"task":"Order these memory regions from the lowest typical address to the highest."}'::jsonb, '{"correctOrderIds":["code","data","heap","stack"]}'::jsonb),
  ('mission-w17-03-o1-c1', 'mission-w17-03-o1', 1, 'multiple_choice', 'int x = 5; int y = 10; int *p = &x; p = &y; *p = 20; What is x after this code runs?', '{"question":"int x = 5; int y = 10; int *p = &x; p = &y; *p = 20; What is x after this code runs?","options":[{"id":"a","text":"5"},{"id":"b","text":"10"},{"id":"c","text":"20"},{"id":"d","text":"It''s undefined behavior"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-w17-04-o1-c1', 'mission-w17-04-o1', 1, 'interactive_diagram', 'Put these stages of building a runnable program in the correct order.', '{"hotspots":[{"id":"preprocess","label":"Preprocessing","explanation":"Expands #include and #define directives, strips comments, produces plain C."},{"id":"compile","label":"Compilation","explanation":"Translates preprocessed C source into assembly for the target architecture."},{"id":"assemble","label":"Assembly","explanation":"Converts assembly into machine code, producing an object file (.o)."},{"id":"link","label":"Linking","explanation":"Combines object files and libraries, resolves symbol references, produces the final executable."}],"task":"Put these stages of building a runnable program in the correct order."}'::jsonb, '{"correctOrderIds":["preprocess","compile","assemble","link"]}'::jsonb),
  ('mission-w17-05-o1-c1', 'mission-w17-05-o1', 1, 'interactive_diagram', 'Put these steps of calling a function in the order they actually happen, using the standard stack-based calling convention.', '{"hotspots":[{"id":"push_args","label":"Arguments are placed for the callee (registers or pushed onto the stack)","explanation":"The caller prepares the values the function will need before transferring control."},{"id":"call_ret","label":"The call instruction pushes the return address","explanation":"So the callee knows exactly where to resume the caller when it finishes."},{"id":"push_bp","label":"The callee saves the caller''s base pointer","explanation":"Preserves the caller''s stack frame so it can be restored later."},{"id":"set_bp","label":"The callee sets its own base pointer to the current stack pointer","explanation":"Establishes a fixed reference point for this function''s own locals and arguments."},{"id":"alloc_locals","label":"The callee allocates space for its local variables","explanation":"Moves the stack pointer further to reserve room for this frame''s own data."}],"task":"Put these steps of calling a function in the order they actually happen."}'::jsonb, '{"correctOrderIds":["push_args","call_ret","push_bp","set_bp","alloc_locals"]}'::jsonb),
  ('mission-w17-06-o1-c1', 'mission-w17-06-o1', 1, 'investigation', 'Which evidence explains exactly how the replica transforms its input buffer?', '{"evidence":[{"id":"loop1","label":"Core loop, decompiled","detail":"for (i = 0; i < len; i++) { out[i] = in[i] ^ key[i % keylen]; }"},{"id":"keydef","label":"Key buffer","detail":"A fixed 8-byte array embedded in the binary''s data segment, never modified at runtime"},{"id":"unrelated1","label":"Logging routine","detail":"Writes a timestamp to a debug log on every call -- has no effect on the output buffer"},{"id":"unrelated2","label":"Network stub","detail":"A stripped-out function that would have sent the output somewhere -- disabled in this replica"}],"question":"Which evidence explains exactly how the replica transforms its input buffer?"}'::jsonb, '{"requiredEvidenceIds":["loop1","keydef"]}'::jsonb),
  ('mission-w17-06-o2-c1', 'mission-w17-06-o2', 1, 'multiple_choice', 'Given a repeating-key XOR transform, how do you recover the original input from the output buffer?', '{"question":"Given a repeating-key XOR transform, how do you recover the original input from the output buffer?","options":[{"id":"a","text":"You can''t -- XOR is one-way"},{"id":"b","text":"XOR the output buffer with the same key, byte by byte, using the same repeating pattern"},{"id":"c","text":"Reverse the byte order of the output buffer"},{"id":"d","text":"Subtract the key value from each output byte"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-w17-06-o3-c1', 'mission-w17-06-o3', 1, 'boss_encounter', 'Submit the full explanation: the transformation and the recovered token.', '{"stages":[{"objectiveRef":"mission-w17-06-o1","label":"The transformation"},{"objectiveRef":"mission-w17-06-o2","label":"The recovery method"}],"task":"Submit the full explanation: the transformation and the recovered token."}'::jsonb, '{"requiredObjectiveIds":["mission-w17-06-o1","mission-w17-06-o2"],"allCorrect":true}'::jsonb);
insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-w17-01-o1-c1', 'orientation', 'There''s nothing to solve here -- just confirm you''re ready to continue.', 0, 1),
  ('mission-w17-02-o1-c1', 'orientation', 'Fixed-size things set at compile time sit at one end; things that grow while the program runs sit toward the other.', 10, 1),
  ('mission-w17-02-o1-c1', 'concept', 'Code and global data don''t change size after compilation. The heap and stack both grow, but in opposite directions toward each other.', 20, 2),
  ('mission-w17-02-o1-c1', 'solution', 'Code sits lowest (fixed, read-only), then global/static data (fixed size, mutable), then the heap (grows upward), then the stack (grows downward from the top).', 30, 3),
  ('mission-w17-03-o1-c1', 'orientation', 'p gets reassigned before anything is written through it -- track what p points to at the moment of the write, not at the start.', 15, 1),
  ('mission-w17-03-o1-c1', 'concept', '*p = 20 only affects whatever p is currently pointing to, not whatever it used to point to.', 25, 2),
  ('mission-w17-03-o1-c1', 'tool_direction', 'Walk through the code line by line: what does p point to right before *p = 20 executes?', 35, 3),
  ('mission-w17-03-o1-c1', 'solution', 'p is reassigned to &y before the write, so *p = 20 sets y to 20 -- x is never touched and stays 5.', 45, 4),
  ('mission-w17-04-o1-c1', 'orientation', 'The compiler never sees your #include and #define directives directly -- something handles those first.', 10, 1),
  ('mission-w17-04-o1-c1', 'concept', 'Each stage consumes the previous stage''s output: text in, text out, until assembly produces actual machine code.', 20, 2),
  ('mission-w17-04-o1-c1', 'solution', 'Preprocessing expands directives, compilation turns that into assembly, assembly produces an object file, and linking combines object files/libraries into the final executable.', 30, 3),
  ('mission-w17-05-o1-c1', 'orientation', 'The caller has to prepare everything the callee needs before control ever transfers.', 15, 1),
  ('mission-w17-05-o1-c1', 'concept', 'The return address is pushed automatically by the call instruction itself, before the callee code runs at all.', 25, 2),
  ('mission-w17-05-o1-c1', 'tool_direction', 'Think about what the callee needs saved before it can safely use the stack for its own locals.', 35, 3),
  ('mission-w17-05-o1-c1', 'solution', 'Arguments are prepared, then call pushes the return address, then the callee saves the old base pointer, sets its own base pointer, and finally allocates space for its locals.', 45, 4),
  ('mission-w17-06-o1-c1', 'orientation', 'Two of these four items actually touch the output buffer. The other two are unrelated behavior.', 20, 1),
  ('mission-w17-06-o1-c1', 'concept', 'A repeating key applied byte-by-byte with XOR is a very specific, very recognizable pattern.', 30, 2),
  ('mission-w17-06-o1-c1', 'tool_direction', 'Compare the loop''s indexing against the key buffer''s length.', 40, 3),
  ('mission-w17-06-o1-c1', 'solution', 'The decompiled loop XORs each input byte against a repeating 8-byte key -- that key buffer, combined with the loop, is the entire transformation. The logging and network stub don''t touch the output.', 50, 4),
  ('mission-w17-06-o2-c1', 'orientation', 'XOR is its own inverse when you reuse the exact same key.', 20, 1),
  ('mission-w17-06-o2-c1', 'solution', 'XOR-ing the output buffer against the same repeating key, byte by byte, reverses the transformation exactly and recovers the original input.', 30, 2),
  ('mission-w17-06-o3-c1', 'orientation', 'You''ve already worked out both halves -- combine the transformation with how to reverse it.', 25, 1),
  ('mission-w17-06-o3-c1', 'concept', 'The explanation needs the mechanism (repeating-key XOR) and the recovery method (XOR again with the same key).', 35, 2),
  ('mission-w17-06-o3-c1', 'tool_direction', 'State what the loop does first, then how reversing it recovers the token.', 45, 3),
  ('mission-w17-06-o3-c1', 'near_solution', 'Repeating-key XOR against an 8-byte embedded key; reverse it by XOR-ing again with that same key.', 55, 4),
  ('mission-w17-06-o3-c1', 'solution', 'The replica XORs each input byte against a repeating 8-byte key embedded in its data segment. XOR-ing the output against that same key, byte by byte, reverses the transform exactly and recovers the hidden token -- which turns out to be a formatted API key.', 65, 5);
